from __future__ import print_function
import time
import timeit
import logging
import json

import os
from requests import codes
from ast import literal_eval
from taf.internal.scf.scf import SCF
from taf.internal.scf.p import P
from taf.internal.scf.list import List
from taf.internal.scf.item import Item
from taf.internal.scf.managed_object import ManagedObject
from taf.internal.scf.exceptions import ElementNotFound
from .exceptions import (ValidationStatusTimeout,
                         ValidationFailure, NiddParameterNotFound, InvalidLocationOptions,
                         SnapshotError, DistNameNotFound, StatusNotSupported)

from .pbts import site_conf_validation
from .common import StatusConfiguration

log = logging.getLogger(__name__)
log.addHandler(logging.NullHandler())


@site_conf_validation
class ResourceBTS(object):
    NAME = 'mz'
    API_VER = 'v1'
    DEFAULT_NO = '1'
    SUBMODULE = 'r'
    ALARM_STATE_ACTIVE = "active"
    ALARM_STATE_HISTORY = "history"
    SAVE_LOCATION_LOCAL = 'LOCAL'
    SAVE_LOCATION_SBTS = 'SBTS'
    SAVE_LOCATION_SERVER = 'SERVER'
    SNAPSHOT_READY_STATE = 'snapshotReady'
    SNAPSHOT_UPLOAD_READY_STATE = 'snapshotUploadReady'
    FAULT_SOURCE = 'additionalText8'
    FAULT_NAME = 'additionalText1'

    def __init__(self, session):
        self.session = session

    def get_specific_url(self, *url_components):
        """Can be called from every MegaZone subclass to get more specific url."""
        components = [self.link()] + list(url_components)
        return '/'.join(components)

    def link(self):
        """Base method for every child class"""
        return '/'.join([self.NAME, self.SUBMODULE, self.API_VER])

    def enter_test_state_ap_l1emu(self):
        return self._enter_state_and_reset('testStateL1EMU')

    def enter_test_state_ap_gw(self):
        return self._enter_state_and_reset('testStateL1GW')

    def enter_test_state_gnb_without_ru(self):
        return self._enter_state_and_reset('GNBWORU')

    def exit_test_state(self):
        return self._enter_state_and_reset('normalState')

    def _enter_state_and_reset(self, state):
        link = 'mz/r/v1/reset'
        payload = {'resetRequest': state}
        payload = json.dumps(payload)
        return self.session.send_request(link, method='PUT', data=payload)

    def perform_commissioning(self, scf_path, timeout=None):
        url = self.get_specific_url('plans', self.DEFAULT_NO)
        self._transfer_scf_to_mz(scf_path, url, timeout=timeout)
        url += '/info'
        self._trigger_commissioning(url)

    def make_snapshot(self, snapshot_path=None, timeout=480, save_location=SAVE_LOCATION_LOCAL, **kwargs):
        self._verify_snapshot_arguments(snapshot_path, save_location)
        kwargs = self._get_correctly_typed_collecting_details(**kwargs)
        resp_json = self.prepare_snapshot(save_location, **kwargs)
        self.session.report_snapshot_error(resp_json)
        self._get_ready_snapshot(resp_json, timeout, save_location)
        if save_location == self.SAVE_LOCATION_LOCAL:
            self.save_snapshot(snapshot_path)

    def _verify_snapshot_arguments(self, snapshot_path, save_location):
        if save_location == self.SAVE_LOCATION_LOCAL and snapshot_path is None:
            raise TypeError('Enter snapshot path')
        if save_location not in {self.SAVE_LOCATION_LOCAL, self.SAVE_LOCATION_SBTS, self.SAVE_LOCATION_SERVER}:
            raise ValueError("Please enter a valid savelocation")

    def _get_correctly_typed_collecting_details(self, **kwargs):
        kwargs_casts = {'type': int, 'level': int, 'rap': lambda x: literal_eval(str(x)), 'vnf': str}

        return {kwarg:
                kwargs_casts[kwarg](kwarg_val) if kwarg in kwargs_casts else kwarg_val
                for kwarg, kwarg_val in kwargs.items()}

    def save_snapshot_from_bts(self, snapshot_path, timeout=480):
        self.save_snapshot(snapshot_path)

    def prepare_snapshot(self, save_location=SAVE_LOCATION_LOCAL, **kwargs):
        if save_location == self.SAVE_LOCATION_SERVER:
            payload = self._prepare_remote_snapshot_payload(**kwargs)
        else:
            payload = self._prepare_local_snapshot_payload(save_location, **kwargs)
        return self._send_prepare_snapshot_request(payload)

    def _send_prepare_snapshot_request(self, payload):
        url = '/'.join([self.link(), 'snapshot'])
        payload = json.dumps(payload)
        resp = self.session.send_request(url, method='PUT', data=payload, verify=False)
        return resp.json()

    def _get_snapshot_payload(self, save_location, request_id='0000', **collecting_details):
        collecting_details = self._prepare_collecting_details(**collecting_details)
        try:
            username = self.session.session.username
        except AttributeError:
            username = ''
        payload = {"changedValues": {"command": "create", "notes": "",
                                     "user": username, "saveLocation": save_location,
                                     "collectingDetails": collecting_details,
                                     "requestID": request_id}}
        return payload

    @staticmethod
    def _prepare_collecting_details(type=0, level=0, rap=None, vnf='on'):
        if rap is None:
            rap = []
        collecting_details = {'type': type, 'level': level, 'rap': rap, 'vnf': vnf}
        return collecting_details

    def _prepare_local_snapshot_payload(self, save_location, **kwargs):
        local_payload = self._get_snapshot_payload(save_location, **kwargs)
        return local_payload

    def _prepare_remote_snapshot_payload(self, protocol='https', ipaddr='', port='8080',
                                         username='', password='', target_path='/home/ute', **kwargs):
        remote_payload = self._get_snapshot_payload(self.SAVE_LOCATION_SERVER, **kwargs)
        options = self._prepare_remote_location_options(protocol, ipaddr, port, username, password, target_path)
        uri = "{protocol}://{username}:{password}@{host}:{port}{folder}"
        uri = uri.format(**options)
        remote_payload["changedValues"].update(lssData={"uri": uri})
        return remote_payload

    def _prepare_remote_location_options(self, protocol='https', ipaddr='', port='8080',
                                         username='', password='', target_path='/home/ute'):
        self._verify_remote_location_options(ipaddr, username, password, target_path)
        options = {
            'protocol': protocol,
            'host': ipaddr,
            'port': port,
            'username': username,
            'password': password,
            'folder': target_path}
        return options

    @staticmethod
    def _verify_remote_location_options(ipaddr, username, password, target_path):
        mandatory_remote_options = [ipaddr, username, password]
        if not all(mandatory_remote_options):
            raise InvalidLocationOptions("Not all required remote location "
                                         "options passed. Required options: {}".format(mandatory_remote_options))
        if not target_path.startswith('/'):
            raise InvalidLocationOptions("Only absolute paths are allowed, got relative path: {}".format(target_path))

    def _get_ready_snapshot(self, resp_json, timeout, save_location):
        if save_location == self.SAVE_LOCATION_SERVER:
            self._wait_for_snapshot(resp_json, timeout, expected_state=self.SNAPSHOT_UPLOAD_READY_STATE)
        else:
            self._wait_for_snapshot(resp_json, timeout, expected_state=self.SNAPSHOT_READY_STATE)

    def _wait_for_snapshot(self, resp_json, timeout, expected_state, check_time=1):
        url = '/'.join([self.link(), 'snapshot'])
        start = timeit.default_timer()
        while not self._check_if_snapshot_ready(resp_json, expected_state):
            end = timeit.default_timer()
            if end - start > timeout:
                self.session.report_snapshot_timeout_error()
            time.sleep(check_time)
            resp = self.session.send_request(url, verify=False)
            resp_json = resp.json()

    def save_snapshot(self, snapshot_path):
        url = '/'.join([self.link(), 'snapshot', 'result'])
        resp = self.session.send_request(url, headers={'content-type': 'application/octet-stream'}, verify=False)
        if resp.status_code == 200:
            with open(snapshot_path, 'wb') as snapshot:
                snapshot.write(resp.content)

    @staticmethod
    def _check_if_snapshot_ready(resp, expected_state):
        snapshot_state = resp['snapshotState']
        if snapshot_state == expected_state:
            return True
        elif snapshot_state in ['snapshotFailed', 'snapshotUploadFailed']:
            feedback = resp['feedback']
            error_msg = 'Snapshot failed: {}'.format(feedback)
            raise SnapshotError(error_msg)
        return False

    def set_default_external_server(self, **remote_location_options):
        url = '/'.join([self.link(), 'snapshot'])
        default_ext_server_options = self._prepare_remote_location_options(**remote_location_options)
        payload = {'changedValues': {'command': 'setdefaultexternalserver',
                                     'defaultExtServer': default_ext_server_options}}
        self.session.send_request(url, method='PUT', data=json.dumps(payload))

    def is_snapshot_ongoing(self, timeout=None):
        """
        Checks whether snapshot collection is currently ongoing ('snapshotOngoing' state).

        :param timeout: (optional) Timeout for getting response, defaults to None (indefinite).
        :return: True if snapshot state is 'snapshotOngoing', False otherwise.
        :rtype: bool
        """
        url = '/'.join([self.link(), 'snapshot'])
        resp = self.session.send_request(url, verify=False, timeout=timeout)
        json = resp.json()
        snapshot_state = json.get('snapshotState', None)
        return snapshot_state == 'snapshotOngoing' if snapshot_state else False

    def get_faults(self, state=ALARM_STATE_ACTIVE, timeout=None):
        faults = list(filter(self._is_fault, self._request_alarms(state, timeout=timeout)))
        return faults

    def get_alarms(self, state=ALARM_STATE_ACTIVE, timeout=None):
        alarms = self._request_alarms(state, timeout=timeout)
        return alarms

    def _request_alarms(self, state, timeout):
        url = self.get_specific_url("alarm?state={}".format(state))
        resp = self.session.send_request(url, method='GET', verify=False, timeout=timeout)
        return resp.json()

    def _is_fault(self, alarm):
        return not alarm['isRCP']

    def _transfer_scf_to_mz(self, scf_path, url, timeout):
        with open(scf_path) as scf:
            payload = scf.read()
            self.session.send_request(url, method='PUT', headers={'content-type': 'application/xml'},
                                      data=payload, timeout=timeout)

    def _trigger_commissioning(self, url):
        payload = {'operation': 'activate'}
        payload = json.dumps(payload)
        scf_resp = self.session.send_request(url, method='PUT', data=payload)
        if not scf_resp.status_code == codes.ok:
            scf_resp.raise_for_status()

    def validate_scf(self, scf_path, max_retry=10, timeout=None):
        url = self.get_specific_url('plans', self.DEFAULT_NO)
        self._transfer_scf_to_mz(scf_path, url, timeout=timeout)
        self._activate_scf_validation(timeout=timeout)
        resp = self._retry_until_validation_completed(max_retry=max_retry, timeout=timeout)
        self._validate_scf_mainstate(resp)

    def _activate_scf_validation(self, timeout):
        url = self.get_specific_url('plans', self.DEFAULT_NO, 'info')
        payload = json.dumps({'operation': 'validate'})
        self.session.send_request(url, method='PUT', data=payload, timeout=timeout)

    def _retry_until_validation_completed(self, max_retry, timeout):
        retry_count = 1
        validation_interval = 0.1
        validation_response = self._get_validation_status(timeout=timeout)
        while validation_response[0] != 'validationCompleted':
            retry_count += 1
            time.sleep(validation_interval)
            validation_response = self._get_validation_status(timeout=timeout)
            if retry_count > int(max_retry):
                msg = 'Validation not completed after {} retries with ' \
                      'status: {}.'.format(retry_count, validation_response[0])
                raise ValidationStatusTimeout(msg)
        return validation_response[1]

    def _get_validation_status(self, timeout):
        resp_json = self._get_validation_resp(timeout=timeout)
        validation_status = resp_json['planInfo']['planOperState']
        return validation_status, resp_json

    def _get_validation_resp(self, timeout):
        url = self.get_specific_url('plans', self.DEFAULT_NO, 'info')
        resp = self.session.send_request(url, timeout=timeout)
        return resp.json()

    def _validate_scf_mainstate(self, resp):
        main_state = resp['planInfo']['mainState']
        if main_state != 'validated':
            if main_state == 'failed':
                self._validation_failed(resp)
            else:
                self._validation_mainstate_unknown(resp, main_state)

    def _validation_failed(self, resp):
        msg = 'Validation ended with failed state.'
        if 'feedbacks' in resp['planInfo'].keys():
            log.error(str(resp['planInfo']['feedbacks']))
        else:
            log.error(str(resp))
        raise ValidationFailure(msg)

    def _validation_mainstate_unknown(self, resp, main_state):
        msg = 'Validation ended with {} state.'.format(main_state)
        log.error(str(resp))
        raise ValidationFailure(msg)

    def _save_scf_to_file(self, content, full_path):
        with open(full_path, 'w') as scf_file:
            scf_file.write(content)

    def get_validation_results(self, timeout=None):
        resp_json = self._get_validation_resp(timeout=timeout)
        try:
            results = resp_json['planInfo']['feedbacks']['results']
            return results
        except KeyError:
            return []

    def get_current_scf_file(self, local_dir_path, file_name, timeout=None):
        content = self.get_current_scf_content(timeout=timeout)
        full_path = os.path.join(local_dir_path, file_name)
        self._save_scf_to_file(content, full_path)
        return full_path

    def get_current_scf_content(self, timeout=None):
        resp_json = self._get_current_scf_fileinfo(timeout=timeout)
        current_scf_content = resp_json['fileContent']
        return current_scf_content

    def get_current_scf_filename(self, timeout=None):
        resp_json = self._get_current_scf_fileinfo(timeout=timeout)
        current_scf_filename = resp_json['fileName']
        return current_scf_filename

    def _get_current_scf_fileinfo(self, timeout):
        url = self.get_specific_url('raml')
        resp = self.session.send_request(url, timeout=timeout)
        return resp.json()

    def get_nidd_parameter(self, dist_name, abbreviation, timeout=None):
        resp = self._get_current_data(timeout=timeout)
        params = self._get_dist_name_attrs(resp, dist_name, 'parameters')
        try:
            return params[abbreviation]
        except KeyError:
            error_msg = '{param_name} in {dist_name} does not exist'.format(param_name=abbreviation,
                                                                            dist_name=dist_name)
            raise NiddParameterNotFound(error_msg)

    def _get_dist_name_attrs(self, all_data, dist_name, attribute):
        if "distName" in all_data and all_data["distName"] == dist_name:
            return all_data[attribute]
        else:
            for _, elem_value in all_data.items():
                if isinstance(elem_value, dict):
                    attr = self._get_dist_name_attrs(elem_value, dist_name, attribute)
                    if attr:
                        return attr
        return {}

    def _get_current_data(self, timeout):
        url = self.get_specific_url('current')
        resp = self.session.send_request(url, timeout=timeout)
        return resp.json()

    def get_package_version_name(self, dist_name, timeout=None):
        resp = self._get_current_data(timeout=timeout)
        version = self._get_dist_name_attrs(resp, dist_name, 'version')
        if not version:
            raise DistNameNotFound('DistName {} not found'.format(dist_name))
        return version

    def get_managed_object_state(self, dist_name, status_name=None, timeout=None):
        resp = self._get_current_data(timeout=timeout)
        params = self._get_dist_name_attrs(resp, dist_name, 'parameters')
        if not params:
            raise DistNameNotFound('DistName {} not found'.format(dist_name))

        if status_name is None:
            statuses_to_get = params.keys()
            supported_statuses = StatusConfiguration.supported_mo_statuses
            statuses_to_get = [status for status in statuses_to_get if status in supported_statuses]
        else:
            if status_name not in StatusConfiguration.supported_mo_statuses:
                raise StatusNotSupported('Provided status {} is not supported'.format(status_name))
            statuses_to_get = [status_name]

        mo_statuses = dict()
        for status in statuses_to_get:
            if status in params.keys():
                mo_statuses[status] = params.get(status)
            else:
                raise StatusNotSupported("Provided status {} is not available for given distName {}".format(
                    status, dist_name))
        return mo_statuses

    def get_pm_files_list(self, timeout=None):
        url = self.get_specific_url('pm/pmFiles')
        response = self.session.send_request(url, method='GET', timeout=timeout)
        return response.json()

    def get_pm_file_content(self, pm_filename, timeout=None):
        url = self.get_specific_url('pm/pmFilesData/{}'.format(pm_filename))
        response = self.session.send_request(url, method='GET', timeout=timeout)
        return response.content

    def get_counters_info(self, timeout=None):
        url = self.get_specific_url('pm/countersDescription')
        response = self.session.send_request(url, method='GET', timeout=timeout)
        return response.json()

    def get_counter_info_by_name(self, name, timeout=None):
        return self.get_counters_info(timeout=timeout)[name]

    def _reset_device(self, device_name, device_id='1'):
        """Supported devices are fsm, fbb and frm."""
        reset_endpoint = self.get_specific_url('reset')
        device_pbts_uri = '/'.join(['/mz/p/v1/pbts/1', device_name, device_id])
        data = json.dumps({'resetRequest': "unit",
                           'resetUri': device_pbts_uri,
                           'external': 'true'})
        return self.session.send_request(reset_endpoint, method='PUT', data=data).json()

    def reset_fbb(self, fbb_id):
        return self._reset_device('fbb', fbb_id)

    def frm_reset(self, frm_id):
        return self._reset_device('frm', frm_id)

    def fsm_reset(self, fsm_id):
        return self._reset_device('fsm', fsm_id)

    def save_current_data_as_scf(self, scf_path, include_hw=False, timeout=10.0):
        current_data = self._get_current_data(timeout)
        managed_objects_data = self._extract_managed_objects_from_current_data(current_data)
        scf = self._create_scf_from_managed_objects_data(managed_objects_data, include_hw)
        scf.save(scf_path)

    def _extract_managed_objects_from_current_data(self, current, managed_objects_storage=[]):
        managed_object_key = 'properties'
        if isinstance(current, dict):
            try:
                managed_objects_storage.append(current.pop(managed_object_key))
                self._extract_managed_objects_from_current_data(current, managed_objects_storage)
            except KeyError:
                for key in current:
                    self._extract_managed_objects_from_current_data(current[key], managed_objects_storage)
        return managed_objects_storage

    def _create_scf_from_managed_objects_data(self, managed_objects_data, include_hw):
        scf = SCF()
        scf.raml.cmData['scope'] = 'all'

        for managed_object_data in managed_objects_data:
            scf = self._add_managed_object_to_scf(managed_object_data, scf)
        if include_hw is False:
            scf = self._remove_hw_from_scf(scf)
        return scf

    def _add_managed_object_to_scf(self, managed_object_data, scf):
        managed_object = self._create_managed_object(managed_object_data)
        managed_object = self._add_parameters_to_managed_object(managed_object,
                                                                managed_object_data['parameters'])
        scf.raml.cmData.append(managed_object)
        return scf

    @staticmethod
    def _remove_hw_from_scf(scf):
        try:
            for hw_tree in scf.raml.cmData.HW:
                hw_tree.remove_tree()
        except ElementNotFound:
            log.info('Scf tree removal skipped- HW managed object not found')
        return scf

    @staticmethod
    def _create_managed_object(managed_object_data):
        klass = managed_object_data['class']
        dist_name = managed_object_data['distName']
        version = managed_object_data.get('version')
        operation = managed_object_data.get('operation', 'create')
        mo_id = managed_object_data.get('id')
        mo_name = managed_object_data.get('moName')
        vendor = managed_object_data.get('vendor')
        time_stamp = managed_object_data.get('time_stamp')
        mo = ManagedObject().create(klass=klass,
                                    dist_name=dist_name,
                                    version=version,
                                    operation=operation,
                                    id=mo_id,
                                    name=mo_name,
                                    vendor=vendor,
                                    time_stamp=time_stamp)
        return mo

    def _add_parameters_to_managed_object(self, managed_object, parameters):
        for param_name, param_value in parameters.items():
            if isinstance(param_value, list):
                xlist = self._create_scf_list_object(list_name=param_name, list_elements=param_value)
                managed_object.append(xlist)
            else:
                managed_object.append(P().create(name=param_name, value=param_value))
        return managed_object

    def _create_scf_list_object(self, list_name, list_elements):
        xlist = List().create(name=list_name)
        for element in list_elements:
            if len(list_elements) > 0 and isinstance(element, dict):
                item_object = self._add_item_to_list(item=element)
                xlist.append(item_object)
            else:
                xlist.append(P().create(value=element))
        return xlist

    @staticmethod
    def _add_item_to_list(item):
        item_object = Item().create()
        [item_object.append(P().create(name=name, value=value)) for name, value in item.items()]
        return item_object

    def get_bts_status(self, nrbts_number, bts_id, timeout):
        endpoint = 'current/mrbts/{bts_id}/nrbts/{nrbts_number}/properties/parameters/operationalState'.format(
            bts_id=bts_id,
            nrbts_number=nrbts_number)

        url = self.get_specific_url(endpoint)

        return self.session.send_request(url, method='GET', timeout=timeout).json()


@site_conf_validation
class RCurrentSBTS(ResourceBTS):
    def link(self):
        """Returns path to REST resources resp"""
        return '/'.join([super(RCurrentSBTS, self).link(), 'current', 'sbts'])
